-- Two more collaboration projects, written from their public websites:
-- MAT Test (mattest.in) and LegalResume (legalresume.in).
-- Each can be edited or hidden from /admin/collaborations later.

INSERT INTO products (name, slug, tagline, category, summary, description, status, website_url, cta_label, brand_color, accent_color, gallery, content, is_published, sort_order) VALUES ('MAT Test', 'mattest', 'Scholarship test for students, taken online', 'Scholarship & Online Testing', 'An online scholarship test portal: register, take the MCQ test from home, and follow your admit card, results and scholarship from one dashboard.', 'MAT Test is the online portal of the Minds and Talent Test. Students register, see the syllabus for their class, take the 100 question objective test from a desktop browser with anti-cheat monitoring, and track their results and scholarship from a single dashboard.', 'live', 'https://mattest.in/', 'Visit MAT Test', '#1e5eff', '#06b6d4', '[]', '{"highlights":[{"value":"100","label":"MCQs in one test"},{"value":"5","label":"subjects"},{"value":"120","label":"minutes of test time"},{"value":"2x","label":"scholarship cycles a year"}],"problems":[],"features":[{"title":"Online registration","text":"Create your student account and apply from home in a few minutes."},{"title":"Syllabus for every class","text":"Separate syllabus for Class 5 to 8, Class 9 and 10, Class 11 and 12, and Bachelors."},{"title":"Secure online exam","text":"Take the test from a desktop browser, with tab switching monitored to keep it fair."},{"title":"Admit card on your dashboard","text":"Your official hall ticket is generated right in your student dashboard."},{"title":"Results with breakdown","text":"See your score and subject-wise performance once results are published."},{"title":"Scholarship board","text":"Rank-based scholarships, with awards and certifications listed clearly."}],"steps":[{"title":"Register","text":"Create your student account in a couple of minutes."},{"title":"Upload and pay","text":"Upload your documents and complete the processing fee online."},{"title":"Take the test","text":"Download your admit card and sit the online exam on the scheduled day."},{"title":"Get your result","text":"View your merit result and claim your scholarship."}],"audience":["Students from Class 5 to Bachelors","Families looking for scholarships","Schools and agents"],"plans":[],"faqs":[{"question":"Who can take the test?","answer":"Students from Class 5 to Bachelors. Each class group has its own syllabus."},{"question":"How is the test taken?","answer":"Online, from a desktop browser (Chrome, Edge or Firefox), within a fixed 120 minute window."}]}', 1, 3);

INSERT INTO products (name, slug, tagline, category, summary, description, status, website_url, cta_label, brand_color, accent_color, gallery, content, is_published, sort_order) VALUES ('LegalResume', 'legalresume', 'The resume builder made for legal careers', 'Resume & Career Tool', 'Build a legal resume in minutes with an AI builder, check it against hiring software, and publish it as a portfolio link.', 'LegalResume helps advocates, lawyers, law students and legal professionals create a professional resume. Write it yourself or describe changes in English or Hinglish with the AI builder, check your ATS score, export a clean PDF, and publish a portfolio at your own link.', 'live', 'https://legalresume.in/', 'Try LegalResume', '#1d4ed8', '#0ea5e9', '[]', '{"highlights":[{"value":"Free","label":"editor, templates, PDF and ATS check"},{"value":"12","label":"portfolio designs"},{"value":"24x7","label":"live chat support"},{"value":"Hinglish","label":"AI builder understands both"}],"problems":[],"features":[{"title":"AI resume builder","text":"Describe a change in English or Hinglish and the right blocks appear. Undo anything you do not like."},{"title":"Drag and drop editor","text":"Build with blocks, columns and pages for experience, education, moot courts, publications and skills."},{"title":"Templates for legal roles","text":"Traditional, modern and minimal layouts that courts, firms and publications find easy to scan."},{"title":"Free ATS score","text":"Upload a PDF, get a score out of 100, the missing keywords and the fixes to make first."},{"title":"Print-ready PDF","text":"Export a clean A4 or Letter PDF with your email and links still clickable."},{"title":"Portfolio with your own link","text":"Publish a resume website and share one link instead of attachments."}],"steps":[{"title":"Sign in with an email code","text":"No password to remember. Just confirm the code sent to your email."},{"title":"Build or describe","text":"Write your resume yourself, or tell the AI what to add."},{"title":"Check your ATS score","text":"See how hiring software reads your resume and what to fix."},{"title":"Export or publish","text":"Download the PDF or share your portfolio link."}],"audience":["Law students","Litigators","Corporate lawyers","LL.M. applicants","Judiciary aspirants","In-house counsel","Legal researchers","Paralegals"],"plans":[{"name":"Free","price":"Free","note":"Free plan forever","items":["Resume editor","Templates","PDF export","ATS score"]},{"name":"Paid plans","price":"See pricing","note":"Pro, Premium and Ultimate","items":["More AI uses","Portfolio with your own public link"]}],"faqs":[{"question":"Is LegalResume free?","answer":"The editor, templates, PDF export and ATS check are free. Paid plans add more AI and your own portfolio link."},{"question":"Can I write my resume in Hinglish?","answer":"Yes. The AI builder understands English and Hinglish."},{"question":"Do I need a password?","answer":"No. You sign in with an email code."}]}', 1, 4);
